window.RP_SESSION={"id":"S-a2f12af63074","messages":[{"id":"RP-0190401","time":"2026-07-10T22:59:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-0190402","time":"2026-07-10T22:59:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-0190403","time":"2026-07-10T22:59:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-0190404","time":"2026-07-10T23:01:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...자각자각\n\n          ...자각자각\n\n                      ...자각자각","characters":["P-7ba611cf90be"]},{"id":"RP-0190405","time":"2026-07-10T23:02:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"작은 가위가 얇은 천 위를 헤엄치며 가릅니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190406","time":"2026-07-10T23:05:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그는 장작을 패기 위해 받침 용도로 사용하던 낡은 나무 그루터기에 앉아있었습니다.\n\n밑동의 단면에는 나이테가 그득하게, 그리고 그보다 많은 도끼 자국의 흉터가 새겨져 있었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190407","time":"2026-07-10T23:06:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"시장에서 사온 얇고 바람이 잘 통하는 천쪼가리에 숨풍숨풍.\n\n두 개의 눈구멍을 뚫어놓았고, 손가락을 집어넣어 그 너비를 확인해보았습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190408","time":"2026-07-10T23:08:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"반짇고리에서 천과 색이 비슷한 실과 바늘을 꺼내어 구멍을 마감하듯 꿰어냅니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190409","time":"2026-07-10T23:09:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"엉성하게나마 올이 정돈되었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190410","time":"2026-07-10T23:11:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"이제 이걸 먼저 뒤집어쓰고, 가면은 그 위에 쓰면, 땀이 흡수되어서 덜 찝찝하겠죠?","characters":["P-7ba611cf90be"]},{"id":"RP-0190411","time":"2026-07-10T23:11:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"눈 구멍을 안 뚫으니까, 안그래도 흐릿한 오른눈이 거의 안 보이는 수준이더라구요.","characters":["P-7ba611cf90be"]},{"id":"RP-0190412","time":"2026-07-10T23:14:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그는 그렇게, 천을 뒤집어쓴 후 눈 구멍을 정렬하고, 마저 가면을 쓰며 끈을 조였습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190413","time":"2026-07-10T23:14:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190414","time":"2026-07-10T23:15:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"안녕하세요?\"\n참견쟁이 아마이 조가 나타났습니다!\n\"뭐하고 계셨어요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190415","time":"2026-07-10T23:15:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"지크 형씨?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190416","time":"2026-07-10T23:15:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"아니구만. 누구인가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190417","time":"2026-07-10T23:16:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"아아, 전 아마이 조라고 합니다!\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190418","time":"2026-07-10T23:16:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"반갑군. 내 이름은 토르번일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190419","time":"2026-07-10T23:17:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"지크님은 정말 언제 한번 꼭 뵙고 싶군요. 말씀을 너무 많이 들어서.. 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190420","time":"2026-07-10T23:17:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"크큭... 비교 당하는 거 같아서 기분 나쁘지는 않은가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190421","time":"2026-07-10T23:19:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"뭐, 딱히요? 아직 지크님에 대해 잘 모르긴 하지만, 말을 들어보니 저완 많이 다른 스타일의 전투를 하시는 것 같더라구요. 그럼 비교의 의미가 별로 없죠.\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190422","time":"2026-07-10T23:19:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"무엇보다 예술가로썬 무조건 제가 우위일 거 아닙니까, 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190423","time":"2026-07-10T23:20:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"예술가라. 교양인이 들어왔나보군.\"\n\n\"물론 난 전투 스타일이 다르다는 게 더 궁금한데 말일세. 자네는 어찌 싸우길래?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190424","time":"2026-07-10T23:26:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"아마이 조가 붓을 꺼내들고, 순식간에 자신의 몸에 색을 칠합니다..?\n주변환경과 최대한 비슷하게 색칠된 아마이 조..\n아무리 생각해도 어딘가 허접한 기술이지만 자세히 보지 않으면 나름 티가 안 날지도 모르겠군요.\n아마도..?\n\n\"이렇게 숨은 후에 단검으로 기습하거나 하는 식이죠, 헹헹..\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190425","time":"2026-07-10T23:29:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...??\"\n\n가면의 턱 부분을 매만지며 그의 장기를 흥미롭게 봤습니다만...\n\n\"...실전에서 쓸 수 있나? 아니 쓸만할 것 같기는 하군.\"\n\n그러면서도 희한하다는 듯 계속 곱씹습니다.\n\n\"쓸만...하군... 호오... 거참...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190426","time":"2026-07-10T23:29:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"그래도 어두운 데선 은근 잘 먹힙니다, 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190427","time":"2026-07-10T23:31:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"나중에 실전에서 실력 한 번 보도록 하지.\"\n\n\"뭐... 아무튼 질문에 답을 하자면, 가면 안에 쓸 천을 손질하고 있었다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190428","time":"2026-07-10T23:32:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"오호.. 가면은 왜 쓰고 다니시나요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-0190429","time":"2026-07-10T23:33:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음... 뭐. 그냥 그럴 일이 있다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190430","time":"2026-07-10T23:33:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"\"아, 조금 무례했군요, 흠흠..\"\n잠시 헛기침을 하며 덜그럭거립니다.","characters":["P-5d58655d55ce"]},{"id":"RP-0190431","time":"2026-07-10T23:35:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"괜찮다네. 별로 실례는 아니다만, 복잡한 개인사라서 답해줄 순 없겠어.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190432","time":"2026-07-10T23:37:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"고개를 끄덕이며 잠시 침묵하다,\n“토르번 씨는 뭐하는 분이세요?”","characters":["P-5d58655d55ce"]},{"id":"RP-0190433","time":"2026-07-10T23:39:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"사짜 마검사라고 해야하나?\"\n\n그는 킬킬 웃으며 분위기를 바꾸었습니다.\n\n\"기사 같이 생겨선, 기사도 아니고, 마법도 쓸 줄은 아는데 제대로 마법을 배운 마법사도 아니거든.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190434","time":"2026-07-10T23:40:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“오, 마검사! 아마이징~~”\n아마이 조가 박수를 탁! 치며 말합니다.\n“그래도 검과 마법 둘 다 다룰 줄 아신단 거잖아요, 멋진데요?”","characters":["P-5d58655d55ce"]},{"id":"RP-0190435","time":"2026-07-10T23:42:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"검은 그래도 수준급이라 생각하네만. 마법은 글쎄. 기대하지 말게나. 한 두가지 주문을 쓸 줄만 아는 수준이니까.\"\n\n\"음... 그 마저도 급박하면 삑사리가 나.\"\n\n라고 말을 덧붙이며 웃었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0190436","time":"2026-07-10T23:43:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“뭐, 원래 마법이 어렵죠. 저도 이상하게 식물학이나 연금술은 재밌는데 마법 공부는 하나~~~도 재미가 없더라구요?”","characters":["P-5d58655d55ce"]},{"id":"RP-0190437","time":"2026-07-10T23:45:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그럼. 하나~~도 재미없는 게 맞지. 그걸 생업으로 하는 녀석들은 괴짜가 분명해.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190438","time":"2026-07-10T23:47:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“웬만한 예술가들보다도 더 괴짜라고 생각해요. 어떻게 그 지루한 걸 그렇게 깊게 파는지..”\n조가 손사렐 치며 말합니다.\n\n“그럼, 쓰시는 마법이 어떤 마법이에요?”","characters":["P-5d58655d55ce"]},{"id":"RP-0190439","time":"2026-07-10T23:49:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"가장 자주 쓰는 건, 검에 천둥을 새기는 것이지.\"\n\n\"검에 주문을 외우고... 검이 무언가에 부딪히면... 쾅...! 하고 번개를 쏘아낸다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190440","time":"2026-07-10T23:50:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“네?!! 아니아니, 엄청 아마이징한 마법이었잖아요?!”","characters":["P-5d58655d55ce"]},{"id":"RP-0190441","time":"2026-07-10T23:52:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"말로 들으면 대단하지만... 글쎄. 생각보다 쓸 수 있는 상황이 많지 않아서, 차라리 그 시간에 검술 훈련을 더 열심히 할 걸 생각도 있다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190442","time":"2026-07-10T23:54:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“뭐, 본 적은 없지만 전 다른 대부분의 검사완 차별점이 있어서 맘에 들어요. 나중에 실전에서 싸우시는 걸 보는 기회가 온다면 꼭 이 두 눈으로 목격하고 싶군요.. 눈은 없지만서도, 헹헹..”","characters":["P-5d58655d55ce"]},{"id":"RP-0190443","time":"2026-07-10T23:57:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"큭큭... 같이 의뢰를 나가면 볼 수도 있겠지.\"\n\n\"내 언데드를 많이 보진 못했는데 그리 농담을 좋아하는 건 원래 종족 특성인가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190444","time":"2026-07-10T23:59:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“헹헹, 글쎄요? 저 말고 다른 언데드를 본 적이 없어서 모르겠군요.\n아참, 물어볼게 있는데, 혹시 연금술 관련 작업같은 걸 할만한 곳이 있을까요?”","characters":["P-5d58655d55ce"]},{"id":"RP-0190445","time":"2026-07-11T00:01:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"아마 지하에 맥주창고 주변에 라르손 형씨가 쓰는 작업실이 있을 걸.\"\n\n\"크게 관심은 없어서 잘은 모르는데... 나중에 하루종일 맥주 타령하는 드워프 녀석을 보면 물어보라고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190446","time":"2026-07-11T00:02:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“오호, 라르손 씨.. 알려주셔서 감사합니다!”","characters":["P-5d58655d55ce"]},{"id":"RP-0190447","time":"2026-07-11T00:04:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"읏차...\"\n\n반짇고리를 정리하더니 앓는 소리를 내며 그루터기에서 일어서 악수를 건넸습니다.\n\n\"밤이 제법 늦은 것이... 이만 들어가봐야겠군. 대화해서 즐거웠네 아마이 형씨. 지나다니며 인사하자고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0190448","time":"2026-07-11T00:05:00+09:00","room":"RP","name":"아마이 조","profile":"아마이 조","identity":"reviewed","type":"dialogue","body":"“안녕히 주무세요, 조만간 또 봅시다!”\n아마이 조 역시 자리에서 일어납니다.","characters":["P-5d58655d55ce"]},{"id":"RP-0190449","time":"2026-07-11T00:05:00+09:00","room":"RP","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-0190450","time":"2026-07-11T00:05:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
